def chunk_overlap(text: str, max_len: int, overlap: int) -> list:
    if max_len <= 0 or not text:
        return []
    if len(text) <= max_len:
        return [text]

    stride = max(1, max_len - overlap)
    chunks = []
    start = 0
    n = len(text)

    while start < n:
        chunks.append(text[start:start + max_len])
        if start + max_len >= n:
            break
        start += stride

    return chunks

